#include "stdlib/blas/ext/base/ndarray/dcusumkbn.h"
#include "stdlib/blas/ext/base/dcusumkbn.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/ndarray/ctor.h"
#include <stdint.h>

/**
* Checks configured integer width before narrowing or advancing indices.
*
* @param N       length
* @param stride  element stride
* @param offset  starting element index
* @return        whether the strided kernel's integer arithmetic is representable
*/
static int8_t valid_indices( const int64_t N, const int64_t stride, const int64_t offset ) {
	const int64_t hi = ( sizeof(CBLAS_INT) == sizeof(int64_t) ) ? INT64_MAX : INT32_MAX;
	const int64_t lo = ( sizeof(CBLAS_INT) == sizeof(int64_t) ) ? INT64_MIN : INT32_MIN;
	uint64_t magnitude;
	uint64_t distance;

	if ( N <= 0 || N > hi || stride < lo || stride > hi || offset < 0 || offset > hi ) {
		return 0;
	}
	if ( stride >= 0 ) {
		return stride <= (hi-offset)/N;
	}
	// Compute magnitude without negating INT64_MIN.
	magnitude = (uint64_t)( -(stride+1) ) + 1;
	if ( N > 1 && magnitude > (uint64_t)offset/(uint64_t)(N-1) ) {
		return 0;
	}
	// Offset-to-minimum distance can span the full unsigned 64-bit range.
	distance = (uint64_t)offset + (uint64_t)( -(lo+1) ) + 1;
	return magnitude <= distance/(uint64_t)N;
}

/**
* Computes compensated cumulative prefixes using the adopted strided kernel.
*
* The list contains two valid one-dimensional float64 ndarrays and a valid
* zero-dimensional float64 initial value. Physical bounds are caller supplied.
* Indexed and post-iteration arithmetic must fit configured CBLAS_INT.
* Invalid dtype/dimensions or unrepresentable metadata leave output unchanged.
*
* @param arrays  input, output, and initial sum ndarrays
*/
void stdlib_blas_ext_dcusumkbn( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *y = arrays[ 1 ];
	const struct ndarray *initial = arrays[ 2 ];
	double sum;

	if ( stdlib_ndarray_dtype( x ) != STDLIB_NDARRAY_FLOAT64 || stdlib_ndarray_dtype( y ) != STDLIB_NDARRAY_FLOAT64 || stdlib_ndarray_dtype( initial ) != STDLIB_NDARRAY_FLOAT64 || stdlib_ndarray_ndims( x ) != 1 || stdlib_ndarray_ndims( y ) != 1 || stdlib_ndarray_ndims( initial ) != 0 ) {
		return;
	}
	if ( stdlib_ndarray_get_float64( initial, NULL, &sum ) != 0 ) {
		return;
	}
	const int64_t N = stdlib_ndarray_dimension( x, 0 );
	if ( N <= 0 ) {
		return;
	}
	if ( stdlib_ndarray_stride( x, 0 ) % 8 != 0 || stdlib_ndarray_stride( y, 0 ) % 8 != 0 || stdlib_ndarray_offset( x ) % 8 != 0 || stdlib_ndarray_offset( y ) % 8 != 0 ) {
		return;
	}
	const int64_t sx = stdlib_ndarray_stride_elements( x, 0 );
	const int64_t sy = stdlib_ndarray_stride_elements( y, 0 );
	const int64_t ox = stdlib_ndarray_offset_elements( x );
	const int64_t oy = stdlib_ndarray_offset_elements( y );
	if ( !valid_indices( N, sx, ox ) || !valid_indices( N, sy, oy ) ) {
		return;
	}
	API_SUFFIX(stdlib_strided_dcusumkbn_ndarray)( (CBLAS_INT)N, sum, (const double *)stdlib_ndarray_data( x ), (CBLAS_INT)sx, (CBLAS_INT)ox, (double *)stdlib_ndarray_data( y ), (CBLAS_INT)sy, (CBLAS_INT)oy );
}
